def main():
    print(f"[*] Validating and building verified dataset of {len(VERIFIED_100_BUSINESSES)} records...")
    assert len(VERIFIED_100_BUSINESSES) == 100, f"Expected exactly 100 records, got {len(VERIFIED_100_BUSINESSES)}"

    names = set()
    phones = set()
    for item in VERIFIED_100_BUSINESSES:
        n = item.get("business_name")
        assert n not in names, f"Duplicate name: {n}"
        names.add(n)
        p = item.get("phone")
        if p:
            p_clean = p.replace(" ", "").replace("+91", "").replace("-", "")[-10:]
            if len(p_clean) == 10:
                assert p_clean not in phones, f"Duplicate phone: {p} in {n}"
                phones.add(p_clean)

    os.makedirs(os.path.dirname(OUTPUT_PATH), exist_ok=True)
    with open(OUTPUT_PATH, "w", encoding="utf-8") as f:
        json.dump(VERIFIED_100_BUSINESSES, f, indent=2, ensure_ascii=False)

    print(f"[SUCCESS] Wrote exactly 100 verified healthcare businesses to: {OUTPUT_PATH}")

if __name__ == "__main__":
    main()
